package constants;

/**
 * Moi hang so cua chuong trinh: so cua menu, luat du lieu, dinh dang bang, du lieu mau.
 * Khong viet so hay chuoi thang trong code (thay: "khong hardcode").
 *
 * @author CuongThai Academy
 */
public final class Constants {

    // Lua chon 0: thoat (cung la lua chon nho nhat)
    public static final int MENU_EXIT = 0;

    // Lua chon 1: them sach
    public static final int MENU_ADD = 1;

    // Lua chon 2: danh sach sach
    public static final int MENU_LIST = 2;

    // Lua chon 3: tim sach
    public static final int MENU_SEARCH = 3;

    // Lua chon 4: cap nhat so ban
    public static final int MENU_UPDATE_COPIES = 4;

    // Lua chon 5: xoa sach
    public static final int MENU_DELETE = 5;

    // Lua chon 6: them thanh vien
    public static final int MENU_ADD_MEMBER = 6;

    // Lua chon 7: danh sach thanh vien
    public static final int MENU_LIST_MEMBERS = 7;

    // Lua chon 8: thong ke (cung la lua chon lon nhat)
    public static final int MENU_REPORT = 8;

    // Do dai toi da cua ten sach
    public static final int TITLE_MAX_LENGTH = 60;

    // So chu so cua ISBN-13
    public static final int ISBN_LENGTH = 13;

    // So chu so dau (tien to) cua ISBN-13: 978 hoac 979
    public static final int ISBN_PREFIX_LENGTH = 3;

    // Tien to ISBN-13 thu nhat
    public static final String ISBN_PREFIX_978 = "978";

    // Tien to ISBN-13 thu hai
    public static final String ISBN_PREFIX_979 = "979";

    // Trong so cua chu so o vi tri le (thu 2, 4, ...): 3; vi tri chan: 1
    public static final int ISBN_ODD_WEIGHT = 3;

    // Chia lay du cho 10 khi tinh chu so kiem tra
    public static final int ISBN_MODULO = 10;

    // Cac chu so; vi tri cua 1 ky tu trong chuoi nay chinh la gia tri cua no
    public static final String DIGITS = "0123456789";

    // Hai ky tu duoc phep go xen trong ISBN (se bi bo di)
    public static final String ISBN_SEPARATORS = "- ";

    // Nam xuat ban nho nhat (sach in dau tien cua Gutenberg ~1450)
    public static final int YEAR_MIN = 1450;

    // So ban nho nhat (0 = tam het sach)
    public static final int COPIES_MIN = 0;

    // So ban lon nhat cua 1 dau sach
    public static final int COPIES_MAX = 99;

    // Regex ten nguoi: chu cai khong dau va dau cach
    public static final String REGEX_PERSON_NAME = "[A-Za-z ]+";

    // Regex ma sach: B + 3 chu so (da viet hoa truoc khi so)
    public static final String REGEX_BOOK_ID = "B\\d{3}";

    // Regex email (da viet thuong): ten [a-z0-9] noi bang . _ - ; ten mien co it nhat 1 dau cham
    public static final String REGEX_EMAIL
            = "[a-z0-9]+([._-][a-z0-9]+)*@[a-z0-9]+(-[a-z0-9]+)*(\\.[a-z0-9]+(-[a-z0-9]+)*)+";

    // Regex nhieu dau cach lien nhau (de gop thanh 1)
    public static final String REGEX_SPACES = "\\s+";

    // Mot dau cach
    public static final String SPACE = " ";

    // Dinh dang ma sach: B + so thu tu 3 chu so
    public static final String BOOK_ID_FORMAT = "B%03d";

    // Dinh dang ma thanh vien: M + so thu tu 3 chu so
    public static final String MEMBER_ID_FORMAT = "M%03d";

    // So thu tu dau tien khi cap ma (B001, M001)
    public static final int FIRST_ID_NUMBER = 1;

    // Dinh dang 1 dong bang sach: No, ma, ISBN, nam, so ban, tac gia, ten sach
    public static final String BOOK_TABLE_FORMAT = "%-3s %-5s %-14s %-5s %-6s %-20s %s";

    // Dinh dang 1 dong bang thanh vien: No, ma, ho ten, email
    public static final String MEMBER_TABLE_FORMAT = "%-3s %-5s %-22s %s";

    // Sach mau: { ten sach, ISBN-13, tac gia, nam, so ban }
    public static final String[][] SAMPLE_BOOK_ARRAY = {
        {"The Pragmatic Programmer", "9780135957059", "David Thomas", "2019", "3"},
        {"Effective Java", "9780134685991", "Joshua Bloch", "2018", "2"},
        {"Java Concurrency In Practice", "9780321349606", "Brian Goetz", "2006", "1"},
        {"Head First Java", "9780596009205", "Kathy Sierra", "2005", "4"},
    };

    // Vi tri cot ten sach trong 1 dong mau
    public static final int SAMPLE_TITLE_INDEX = 0;

    // Vi tri cot ISBN trong 1 dong mau
    public static final int SAMPLE_ISBN_INDEX = 1;

    // Vi tri cot tac gia trong 1 dong mau
    public static final int SAMPLE_AUTHOR_INDEX = 2;

    // Vi tri cot nam xuat ban trong 1 dong mau
    public static final int SAMPLE_YEAR_INDEX = 3;

    // Vi tri cot so ban trong 1 dong mau
    public static final int SAMPLE_COPIES_INDEX = 4;

    // Thanh vien mau: { ho ten, email }
