        }
    }

    // Them 1 thanh vien, bao ma vua cap (hoac trung email)
    public void addMember(MemberRequestDTO memberRequestDTO) {
        // Cau ket qua se in
        String resultMessage = "";

        // Kho cap ma va them; trung email thi kho nem loi
        try {
            resultMessage = String.format(Message.SUCCESS_ADD_MEMBER,
                    memberRepository.addMember(memberRequestDTO), memberRequestDTO.getName(),
                    memberRepository.countMembers());
        } catch (Exception e) {
            // Trung email thi lay cau bao loi cua kho
            resultMessage = e.getMessage();
        }

        // In ket qua 1 lan
        showResult(resultMessage, new ArrayList<MemberResponseDTO>());
    }

    // In moi thanh vien, sap theo ho ten
    public void showAllMembers() {
        // Kho tra ban sao, Service sap xep + danh so
        List<MemberResponseDTO> sortedList
                = memberService.sortByName(memberRepository.findAll());

        // Rong thi chi in cau bao rong, nguoc lai chi in bang
        if (sortedList.isEmpty()) {
            showResult(Message.EMPTY_MEMBER_LIST, sortedList);
        } else {
            // Co thanh vien thi in bang
            showResult("", sortedList);
        }
    }

    // Dua cau thong bao + cac dong bang cho View roi goi in dung 1 lan
    private void showResult(String message, List<MemberResponseDTO> responseList) {
        memberView.setMessage(message);
        memberView.setResponseList(responseList);
        memberView.display();
    }

    // Nap cac thanh vien mau khai trong Constants
    private void loadSampleMembers() throws Exception {
        // Moi dong mau: { ho ten, email }
        for (String[] rowArray : Constants.SAMPLE_MEMBER_ARRAY) {
            memberRepository.addMember(toRequestDTO(rowArray));
        }
    }

    // Doi 1 dong mau (mang chuoi) thanh phieu thanh vien
    private MemberRequestDTO toRequestDTO(String[] rowArray) {
        // Phieu thanh vien moi
        MemberRequestDTO memberRequestDTO = new MemberRequestDTO();

        // Chep ho ten va email cua dong mau vao phieu
        memberRequestDTO.setName(rowArray[Constants.SAMPLE_NAME_INDEX]);
        memberRequestDTO.setEmail(rowArray[Constants.SAMPLE_EMAIL_INDEX]);
        return memberRequestDTO;
    }
}

