    private static String getAuthor(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_AUTHOR);
                return Validation.getAuthor(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi nam xuat ban den khi hop le
    private static int getYear(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_YEAR);
                return Validation.getYear(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi so ban den khi hop le
    private static int getCopies(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_COPIES);
                return Validation.getCopies(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ma sach den khi dung dang
    private static String getBookId(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_BOOK_ID);
