            }
        }
    }

    // Hoi ho ten thanh vien den khi hop le
    private static String getMemberName(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc ca dong roi kiem
            try {
                System.out.print(Message.INPUT_MEMBER_NAME);
                return Validation.getMemberName(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi email den khi dung dang
    private static String getEmail(Scanner scanner) {
        // Lap den khi Validation chap nhan
