 * Man hinh ket qua ve thanh vien: chi in nhung gi Controller da dua vao qua thuoc tinh (setter).
 * Ham in display() khong nhan tham so va duoc goi dung 1 lan cho moi luong xu ly.
 *
 * @author CuongThai Academy
 */
public class MemberView {

    // Cac dong bang thanh vien can in (rong thi khong in bang)
    private List<MemberResponseDTO> responseList;

    // Cau thong bao can in (rong thi khong in)
    private String message;

    // Tao View rong
    public MemberView() {
        responseList = new ArrayList<>();
        message = "";
    }

    // Controller dua cac dong bang vao View
    public void setResponseList(List<MemberResponseDTO> responseList) {
        this.responseList = responseList;
    }

    // Controller dua cau thong bao vao View
    public void setMessage(String message) {
        this.message = message;
    }

    // In ket qua dang giu: cau thong bao (neu co) roi bang thanh vien (neu co)
    public void display() {
        // Co cau thong bao thi in
        if (!message.isEmpty()) {
            System.out.println(message);
        }

        // Co dong bang thi in tieu de cot roi tung dong
        if (!responseList.isEmpty()) {
            System.out.println(String.format(Constants.MEMBER_TABLE_FORMAT, Message.COLUMN_NO,
                    Message.COLUMN_ID, Message.COLUMN_NAME, Message.COLUMN_EMAIL));

            // In tung dong thanh vien
            for (MemberResponseDTO row : responseList) {
                System.out.println(row.toString());
            }
        }
    }
}

