package main;

import constants.Constants;
import constants.Message;
import controller.BookController;
import controller.MemberController;
import dto.BookRequestDTO;
import dto.MemberRequestDTO;
import java.util.Scanner;
import utils.Validation;

/**
 * Diem bat dau cua CT Library: in menu, doc va kiem moi o nhap (qua utils),
 * moi lua chon goi Controller dung 1 lan. Main khong biet sach/thanh vien nam o dau.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Ngan khong cho tao doi tuong Main (Main chi co ham static)
    private Main() {
    }

    // Lap menu den khi chon 0
    public static void main(String[] args) {
        // Ban phim (bien cuc bo, khong static), cac controller, co chay cua vong lap menu
        Scanner scanner = new Scanner(System.in);
        BookController bookController = new BookController();
        MemberController memberController = new MemberController();
        boolean isRunning = true;

        // Lap lai menu sau moi chuc nang
        while (isRunning) {
            // In menu
            System.out.println(Message.MENU_HEADER);
            System.out.println(Message.MENU_BODY);

            // Chay chuc nang nguoi dung chon, moi case goi Controller 1 lan
            switch (getMenuChoice(scanner)) {
                // 1: nhap du thong tin roi them sach
                case Constants.MENU_ADD:
                    System.out.println(Message.TITLE_ADD);
                    bookController.addBook(inputBook(scanner));
                    break;

                // 2: in moi sach sap theo ten
                case Constants.MENU_LIST:
                    System.out.println(Message.TITLE_LIST);
                    bookController.showAllBooks();
                    break;

                // 3: nhap tu khoa roi tim sach
                case Constants.MENU_SEARCH:
                    System.out.println(Message.TITLE_SEARCH);
                    bookController.searchBooks(inputKeyword(scanner));
                    break;

                // 4: nhap ma sach + so ban moi roi cap nhat
                case Constants.MENU_UPDATE_COPIES:
                    System.out.println(Message.TITLE_UPDATE_COPIES);
                    bookController.updateCopies(inputCopiesUpdate(scanner));
                    break;

                // 5: nhap ma sach roi xoa
                case Constants.MENU_DELETE:
                    System.out.println(Message.TITLE_DELETE);
                    bookController.deleteBook(inputBookId(scanner));
                    break;

                // 6: nhap ho ten + email roi them thanh vien
                case Constants.MENU_ADD_MEMBER:
                    System.out.println(Message.TITLE_ADD_MEMBER);
                    memberController.addMember(inputMember(scanner));
                    break;

                // 7: in moi thanh vien sap theo ho ten
                case Constants.MENU_LIST_MEMBERS:
                    System.out.println(Message.TITLE_LIST_MEMBERS);
                    memberController.showAllMembers();
                    break;

                // 8: thong ke thu vien
                case Constants.MENU_REPORT:
                    System.out.println(Message.TITLE_REPORT);
                    bookController.showReport();
                    break;

                // 0: tat co de thoat vong lap
                case Constants.MENU_EXIT:
                    System.out.println(Message.GOODBYE);
                    isRunning = false;
                    break;

                // Khong xay ra: getMenuChoice chi tra ve 0 den 8
                default:
                    break;
            }
        }
    }

    // Nhap du thong tin 1 sach, gom vao 1 phieu DTO moi
    private static BookRequestDTO inputBook(Scanner scanner) {
        // Phieu sach moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap tung o (moi o da kiem va chuan hoa o utils)
        bookRequestDTO.setTitle(getTitle(scanner));
        bookRequestDTO.setIsbn(getIsbn(scanner));
        bookRequestDTO.setAuthor(getAuthor(scanner));
        bookRequestDTO.setYear(getYear(scanner));
        bookRequestDTO.setCopies(getCopies(scanner));
        return bookRequestDTO;
    }

    // Nhap tu khoa tim kiem, gom vao phieu DTO (phieu chi dien ten)
    private static BookRequestDTO inputKeyword(Scanner scanner) {
        // Phieu tim kiem moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Tu khoa la 1 phan cua ten sach
        bookRequestDTO.setTitle(getKeyword(scanner));
        return bookRequestDTO;
    }

    // Nhap ma sach + so ban moi, gom vao phieu DTO (phieu chi dien 2 o)
    private static BookRequestDTO inputCopiesUpdate(Scanner scanner) {
        // Phieu cap nhat moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap ma sach roi so ban moi
        bookRequestDTO.setId(getBookId(scanner));
        bookRequestDTO.setCopies(getCopies(scanner));
        return bookRequestDTO;
    }

    // Nhap ma sach can xoa, gom vao phieu DTO (phieu chi dien ma)
    private static BookRequestDTO inputBookId(Scanner scanner) {
        // Phieu xoa moi
        BookRequestDTO bookRequestDTO = new BookRequestDTO();

        // Nhap ma sach
        bookRequestDTO.setId(getBookId(scanner));
        return bookRequestDTO;
    }

    // Nhap ho ten + email cua 1 thanh vien, gom vao phieu DTO moi
    private static MemberRequestDTO inputMember(Scanner scanner) {
        // Phieu thanh vien moi
        MemberRequestDTO memberRequestDTO = new MemberRequestDTO();

