package model;

/**
 * Mot dau sach trong thu vien (Lab 2: them ma sach, tac gia, nam xuat ban, so ban).
 * JavaBean: truong private, constructor rong public, getter/setter.
 *
 * @author CuongThai Academy
 */
public class Book {

    // Ma sach do kho cap (B001, B002, ...)
    private String id;

    // Ma ISBN-13 (13 chu so, da bo dau - va dau cach)
    private String isbn;

    // Ten sach da chuan hoa (Title Case)
    private String title;

    // Tac gia da chuan hoa (Title Case)
    private String author;

    // Nam xuat ban
    private int year;

    // So ban dang co tren ke
    public int copies;

    // Constructor rong (JavaBean): goi constructor day du voi chuoi rong va so 0
    public Book() {
        this("", "", "", "", 0, 0);
    }

    // Constructor day du thuoc tinh; this.x = x phan biet truong voi tham so cung ten
    public Book(String id, String isbn, String title, String author, int year, int copies) {
        this.id = id;
        this.isbn = isbn;
        this.title = title;
        this.author = author;
        this.year = year;
        this.copies = copies;
    }

    // Tra ve ma sach
    public String getId() {
        return id;
    }

    // Gan ma sach
    public void setId(String id) {
        this.id = id;
    }

    // Tra ve ISBN
