package repository;

import constants.Constants;
import constants.Message;
import dto.BookRequestDTO;
import dto.BookResponseDTO;
import java.util.ArrayList;
import java.util.List;
import model.Book;

/**
 * Kho sach: GIU danh sach Book, cap ma sach va lam CRUD (them, tim, sua so ban, xoa).
 * Ma da cap khong bao gio duoc cap lai, ke ca khi sach bi xoa.
 * Chi Controller goi kho; Service khong bao gio cham vao kho.
 *
 * @author CuongThai Academy
 */
public class BookRepository {

    // Danh sach sach dang co trong thu vien
    private List<Book> bookList;

    // So thu tu se cap cho sach ke tiep (truong cua DOI TUONG kho, khong static)
    private static int nextBookNumber;

    // Tao kho rong, ma dau tien la B001
    public BookRepository() {
        bookList = new ArrayList<>();
        nextBookNumber = Constants.FIRST_ID_NUMBER;
    }

    // Them 1 sach tu phieu nhap, tra ve ma vua cap; ISBN da co thi nem loi
    public String addBook(BookRequestDTO bookRequestDTO) throws Exception {
        // Sach dang giu ISBN nay (null neu chua co) va ma se cap
        Book existingBook = findByIsbn(bookRequestDTO.getIsbn());
        String newId = "";

        // Trung ISBN thi bao ro sach nao dang giu ISBN do
        if (existingBook != null) {
            throw new Exception(String.format(Message.ERROR_DUPLICATE_ISBN,
                    existingBook.getIsbn(), existingBook.getId(), existingBook.getTitle()));
        }

        // Cap ma moi roi tang so thu tu cho lan sau
        newId = String.format(Constants.BOOK_ID_FORMAT, nextBookNumber);
        nextBookNumber++;

        // new Book(...) tao 1 doi tuong moi tren heap; danh sach giu tham chieu toi no
        bookList.add(new Book(newId, bookRequestDTO.getIsbn(), bookRequestDTO.getTitle(),
                bookRequestDTO.getAuthor(), bookRequestDTO.getYear(), bookRequestDTO.getCopies()));
        return newId;
    }

    // Sua so ban cua sach mang ma trong phieu; khong co ma thi nem loi
    public void updateCopies(BookRequestDTO bookRequestDTO) throws Exception {
        // book va phan tu trong bookList cung tro toi MOT doi tuong Book
        Book book = findBookById(bookRequestDTO.getId());

        // Khong co ma thi bao loi
        if (book == null) {
            throw new Exception(String.format(Message.ERROR_BOOK_NOT_FOUND,
                    bookRequestDTO.getId()));
        }

        // Sua qua tham chieu: doi tuong trong danh sach doi theo
        book.setCopies(bookRequestDTO.getCopies());
    }

    // Xoa sach mang ma nay; khong co ma thi nem loi. nextBookNumber KHONG lui lai
    public void deleteBook(String id) throws Exception {
        // TODO Lab 3.4 — book = findBookById(id); null thi throw ERROR_BOOK_NOT_FOUND;
        //   roi bookList.remove(book). KHONG lui nextBookNumber: ma da cap khong bao gio cap lai.
    }

    // Lay BAN SAO 1 sach theo ma; khong co ma thi nem loi
    public BookResponseDTO findById(String id) throws Exception {
        // Sach mang ma nay (null neu khong co)
        Book book = findBookById(id);

        // Khong co ma thi bao loi
        if (book == null) {
            throw new Exception(String.format(Message.ERROR_BOOK_NOT_FOUND, id));
        }

        return toResponseDTO(book);
    }

    // Dem so dau sach dang co
    public int countBooks() {
        return bookList.size();
    }

    // Lay ban sao moi sach (dang dong bang) theo thu tu da them
    public List<BookResponseDTO> findAll() {
        // Danh sach dong bang tra ve
        List<BookResponseDTO> responseList = new ArrayList<>();

        // Moi sach doi thanh 1 dong bang
        for (Book book : bookList) {
            responseList.add(toResponseDTO(book));
        }

        return responseList;
    }

    // Tim sach co ten chua tu khoa (khong phan biet hoa thuong)
    public List<BookResponseDTO> findByKeyword(String keyword) {
        // Danh sach dong bang tim duoc; tu khoa viet thuong de so khong phan biet hoa thuong
        List<BookResponseDTO> foundList = new ArrayList<>();
        String lowerKeyword = keyword.toLowerCase();

        // Duyet tung sach de so ten
        for (Book book : bookList) {
            // Ten chua tu khoa thi giu lai
            if (book.getTitle().toLowerCase().contains(lowerKeyword)) {
                foundList.add(toResponseDTO(book));
            }
        }

        return foundList;
    }

    // Tim sach theo ma; khong co thi tra null
    private Book findBookById(String id) {
        // Duyet tung sach de so ma
        for (Book book : bookList) {
            // So chuoi bang equals, khong bao gio bang ==
            if (book.getId().equals(id)) {
                return book;
            }
        }

        return null;
    }

    // Tim sach theo ISBN; khong co thi tra null
    private Book findByIsbn(String isbn) {
        // Duyet tung sach de so ISBN
        for (Book book : bookList) {
            // So chuoi bang equals, khong bao gio bang ==
            if (book.getIsbn().equals(isbn)) {
                return book;
            }
        }

        return null;
    }

    // Chep du lieu 1 Book sang 1 dong bang MOI (ban sao, khong phai tham chieu toi Book)
    private BookResponseDTO toResponseDTO(Book book) {
        return new BookResponseDTO(book.getId(), book.getIsbn(), book.getTitle(),
                book.getAuthor(), book.getYear(), book.getCopies());
    }
}

