package utils;

import constants.Constants;
import constants.Message;
import java.util.Calendar;

/**
 * Kiem va lam sach chu nguoi dung go: nhan chuoi Main doc duoc, tra ve gia tri sach
 * hoac nem Exception kem cau bao loi noi ro sai o dau. Khong doc ban phim.
 *
 * @author CuongThai Academy
 */
public final class Validation {

    // Ngan khong cho tao doi tuong Validation (chi co ham static)
    private Validation() {
    }

    // Doi chu thanh so nguyen va kiem so nam trong [min, max]
    public static int getChoice(String input, int min, int max) throws Exception {
        // Lua chon sau khi doi
        int choice = 0;

        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            choice = Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong thi bao phai nhap so nguyen
            throw new Exception(Message.ERROR_NOT_INTEGER);
        }

        // Ngoai khoang thi bao khoang dung
        if ((choice < min) || (choice > max)) {
            throw new Exception(String.format(Message.ERROR_CHOICE_RANGE, min, max));
        }

        return choice;
    }

    // Chuan hoa ten sach: bo dau cach thua, moi tu viet hoa chu dau (Title Case)
    public static String getTitle(String input) throws Exception {
        // Ten da chuan hoa
        String title = toTitleCase(input);

        // Rong (hoac chi co dau cach) thi bao loi
        if (title.isEmpty()) {
            throw new Exception(Message.ERROR_TITLE_EMPTY);
        }

        // Ten da chuan hoa dai qua gioi han thi bao do dai
        if (title.length() > Constants.TITLE_MAX_LENGTH) {
            throw new Exception(String.format(Message.ERROR_TITLE_LENGTH, title.length(),
                    Constants.TITLE_MAX_LENGTH));
        }

        return title;
    }

    // Kiem va chuan hoa ten tac gia
    public static String getAuthor(String input) throws Exception {
        return getPersonName(input, Message.FIELD_AUTHOR);
    }

    // Kiem va chuan hoa ho ten thanh vien
    public static String getMemberName(String input) throws Exception {
        return getPersonName(input, Message.FIELD_MEMBER_NAME);
    }

    // Doi chu thanh nam xuat ban: tu YEAR_MIN, khong lon hon nam hien tai cua may
    public static int getYear(String input) throws Exception {
        // Nam sau khi doi
        int year = parseInteger(input, Message.FIELD_YEAR);

        // TODO Lab 3.1 — nam lon hon nam hien tai cua may
        //   (Calendar.getInstance().get(Calendar.YEAR)) thi throw
        //   String.format(Message.ERROR_YEAR_FUTURE, year). Khong viet cung so 2026!

        // Truoc YEAR_MIN thi bao nam nho nhat va so da nhap
        if (year < Constants.YEAR_MIN) {
            throw new Exception(String.format(Message.ERROR_YEAR_MIN, Constants.YEAR_MIN, year));
        }

        return year;
    }

    // Doi chu thanh so ban va kiem trong [COPIES_MIN, COPIES_MAX]
    public static int getCopies(String input) throws Exception {
        // So ban sau khi doi
        int copies = parseInteger(input, Message.FIELD_COPIES);

        // Ngoai khoang thi bao khoang dung va so da nhap
        if ((copies < Constants.COPIES_MIN) || (copies > Constants.COPIES_MAX)) {
            throw new Exception(String.format(Message.ERROR_NUMBER_RANGE, Message.FIELD_COPIES,
                    Constants.COPIES_MIN, Constants.COPIES_MAX, copies));
        }

        return copies;
    }

    // Kiem ma sach: B + 3 chu so, nhan ca chu thuong (b002 -> B002)
    public static String getBookId(String input) throws Exception {
        // Ma da bo dau cach 2 dau va viet hoa
        String bookId = input.trim().toUpperCase();

        // Sai dang thi bao lai dung chu nguoi dung go
        if (!bookId.matches(Constants.REGEX_BOOK_ID)) {
            throw new Exception(String.format(Message.ERROR_BOOK_ID_FORMAT, input.trim()));
        }

        return bookId;
    }

    // Kiem email co ban: co phan truoc @, co ten mien co dau cham sau @
    public static String getEmail(String input) throws Exception {
        // TODO Lab 3.2 — trim + toLowerCase; khong khop Constants.REGEX_EMAIL
        //   (regex moi, chat hon Lab 2)
        //   thi throw String.format(Message.ERROR_EMAIL, chu nguoi dung go).
        return input.trim().toLowerCase();
    }

    // Kiem ISBN-13: bo dau - va dau cach, du 13 chu so, dau 978/979, dung chu so kiem tra
    public static String getIsbn(String input) throws Exception {
        // Ban go, cac chu so gom duoc, tien to, tong co trong so, chu so kiem tra, chu so cuoi
        String text = input.trim();
        StringBuilder digitBuilder = new StringBuilder();
        String prefix = "";
        int weightedSum = 0;
        int checkDigit = 0;
        int lastDigit = 0;

        // Duyet tung ky tu: chu so thi giu, dau - / dau cach thi bo, con lai la loi
        for (int i = 0; i < text.length(); i++) {
            // Ky tu dang xet
            char character = text.charAt(i);

            // Chu so thi giu lai
            if (Constants.DIGITS.indexOf(character) >= 0) {
                digitBuilder.append(character);
            } else if (Constants.ISBN_SEPARATORS.indexOf(character) < 0) {
                // Khong phai chu so cung khong phai dau ngan cach: chi ro ky tu va vi tri
                throw new Exception(String.format(Message.ERROR_ISBN_CHARACTER, character, i + 1));
            }
        }

        // Thieu hoac thua chu so thi bao so chu so dang co
        if (digitBuilder.length() != Constants.ISBN_LENGTH) {
            throw new Exception(String.format(Message.ERROR_ISBN_LENGTH, Constants.ISBN_LENGTH,
                    digitBuilder.length()));
        }

        // Lay 3 chu so dau
        prefix = digitBuilder.substring(0, Constants.ISBN_PREFIX_LENGTH);

        // Ba chu so dau phai la 978 hoac 979
        if ((!prefix.equals(Constants.ISBN_PREFIX_978)) &&
                (!prefix.equals(Constants.ISBN_PREFIX_979))) {
            throw new Exception(String.format(Message.ERROR_ISBN_PREFIX, prefix));
        }

        // Cong 12 chu so dau: vi tri chan nhan 1, vi tri le nhan 3
        for (int i = 0; i < (Constants.ISBN_LENGTH - 1); i++) {
            // Gia tri cua chu so thu i
            int digit = Constants.DIGITS.indexOf(digitBuilder.charAt(i));

            // Vi tri le (1, 3, 5...) nhan 3, vi tri chan nhan 1
            if ((i % 2) == 1) {
                weightedSum = weightedSum + (digit * Constants.ISBN_ODD_WEIGHT);
            } else {
                // Vi tri chan giu nguyen
                weightedSum = weightedSum + digit;
            }
        }

        // Chu so kiem tra = (10 - tong % 10) % 10
        checkDigit = (Constants.ISBN_MODULO - (weightedSum % Constants.ISBN_MODULO))
                % Constants.ISBN_MODULO;

        // Gia tri chu so cuoi (chu so thu 13)
        lastDigit = Constants.DIGITS.indexOf(digitBuilder.charAt(Constants.ISBN_LENGTH - 1));

        // Chu so cuoi khac chu so tinh ra thi bao ca hai
        if (lastDigit != checkDigit) {
            throw new Exception(String.format(Message.ERROR_ISBN_CHECKSUM, checkDigit, lastDigit));
        }

        return digitBuilder.toString();
    }

    // Kiem tu khoa tim kiem: bo dau cach 2 dau, khong duoc rong
    public static String getKeyword(String input) throws Exception {
        // Tu khoa bo dau cach 2 dau
        String keyword = input.trim();

        // Rong thi bao loi
        if (keyword.isEmpty()) {
            throw new Exception(Message.ERROR_KEYWORD_EMPTY);
        }

        return keyword;
    }

    // Kiem ten nguoi (chi chu cai khong dau + dau cach) roi chuan hoa Title Case
    private static String getPersonName(String input, String fieldName) throws Exception {
        // Ten da chuan hoa
        String name = toTitleCase(input);

        // Rong hoac co ky tu khac chu cai / dau cach thi bao loi kem ten o nhap
        if (!name.matches(Constants.REGEX_PERSON_NAME)) {
            throw new Exception(String.format(Message.ERROR_PERSON_NAME, fieldName));
        }

        return name;
    }

    // Doi chu thanh so nguyen; go chu thi bao loi kem ten o nhap
    private static int parseInteger(String input, String fieldName) throws Exception {
        // Thu doi chu sang so nguyen (bo dau cach 2 dau truoc)
        try {
            return Integer.parseInt(input.trim());
        } catch (NumberFormatException e) {
            // Go chu, so thuc hoac de trong thi bao phai nhap so nguyen
            throw new Exception(String.format(Message.ERROR_NUMBER_FORMAT, fieldName));
        }
    }

    // Bo dau cach thua, moi tu viet hoa chu dau (chuoi rong thi tra chuoi rong)
    private static String toTitleCase(String input) {
        // Chu bo dau cach 2 dau; bo noi cac tu da chuan hoa (khong dung String +=)
        String text = input.trim();
        StringBuilder resultBuilder = new StringBuilder();

        // Rong thi tra luon chuoi rong (noi goi tu bao loi)
        if (text.isEmpty()) {
            return text;
        }

        // Tach theo 1 hay nhieu dau cach, chuan hoa tung tu
        for (String word : text.split(Constants.REGEX_SPACES)) {
            // Tu thu 2 tro di thi them 1 dau cach phia truoc
            if (resultBuilder.length() > 0) {
                resultBuilder.append(Constants.SPACE);
            }

            // Chu dau viet hoa, phan con lai viet thuong
            resultBuilder.append(word.substring(0, 1).toUpperCase());
            resultBuilder.append(word.substring(1).toLowerCase());
        }

        return resultBuilder.toString();
    }
}
